// @module vendor-frontend | Vendora v1.0 | SPIT Mini Project AY 2026-27
import { useState } from 'react';
import { getErrorMessage, vendorAPI } from '../../services/api';
const next={pending:'processing',processing:'shipped',shipped:'delivered'};
export default function OrdersTable({ orders = [], onUpdateStatus }) {
  const [selections,setSelections]=useState({}); const [busy,setBusy]=useState(null); const [error,setError]=useState('');
  const update=async(order)=>{const status=selections[order.order_id]||next[order.status];if(!status)return;setBusy(order.order_id);setError('');try{await vendorAPI.updateOrderStatus(order.order_id,status);onUpdateStatus?.(order.order_id,status);}catch(e){setError(getErrorMessage(e));}finally{setBusy(null);}};
  return <div>{error&&<p className="mb-3 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<div className="overflow-x-auto rounded-2xl border border-slate-200 bg-white"><table className="min-w-full text-left text-sm"><thead className="bg-slate-50 text-[10px] font-bold uppercase tracking-wider text-slate-500"><tr><th className="px-4 py-3">Order</th><th className="px-4 py-3">Customer</th><th className="px-4 py-3">Items</th><th className="px-4 py-3">Vendor Total</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Action</th></tr></thead><tbody className="divide-y divide-slate-100">{orders.map((order)=><tr key={order.order_id} className="hover:bg-violet-50/40"><td className="px-4 py-3 font-bold">#{order.order_id}<p className="text-xs font-normal text-slate-400">{new Date(order.created_at).toLocaleDateString()}</p></td><td className="px-4 py-3"><p className="font-semibold">{order.customer_name}</p><p className="text-xs text-slate-400">{order.customer_email}</p></td><td className="px-4 py-3"><div className="max-w-xs space-y-1">{order.items.map((i)=><p key={i.item_id} className="truncate text-xs text-slate-600">{i.quantity}× {i.product_name}</p>)}</div></td><td className="px-4 py-3 font-mono font-bold">₹{Number(order.vendor_total).toLocaleString('en-IN')}</td><td className="px-4 py-3"><span className="rounded-full bg-slate-100 px-2 py-1 text-xs font-bold capitalize text-slate-700">{order.status}</span></td><td className="px-4 py-3">{next[order.status]?<div className="flex gap-2"><select value={selections[order.order_id]||next[order.status]} onChange={(e)=>setSelections({...selections,[order.order_id]:e.target.value})} className="rounded-lg border-slate-200 py-1.5 text-xs focus:border-violet-500 focus:ring-violet-500"><option value={next[order.status]}>Mark {next[order.status]}</option></select><button disabled={busy===order.order_id} onClick={()=>update(order)} className="rounded-lg bg-violet-600 px-3 py-1.5 text-xs font-bold text-white disabled:opacity-50">{busy===order.order_id?'…':'Update'}</button></div>:<span className="text-xs font-semibold text-emerald-600">Complete</span>}</td></tr>)}</tbody></table>{!orders.length&&<div className="p-10 text-center text-sm text-slate-500">No orders found.</div>}</div></div>;
}
